// === Tab: mySketch ===
/*
Plant fork of: https://editor.p5js.org/BarneyCodes/sketches/Bw6Oa77_r 
	With awesome guided vid!:https://www.youtube.com/watch?v=3Mu0--aGfqg about L-Systems
	L-Systems Info: https://en.wikipedia.org/wiki/L-system
Song: Created by myself and AI from Suno.com! inspired by The Airborne Toxic Event - Sometime Around Midnight: https://www.youtube.com/watch?v=UYPoMjR6-Ao

There is a 25% chance you might see red roses/flowers 15 seconds in - not sure why that is! If that happens just refresh! 
red roses/flowers should appear when a heavey bass hits


Hope you all enjoy! 

																				Bonus: Find the eval() in my code, to unlock a mini game!

*/

let B=0 //Bass of Music
let branchColor = []
let len = 4;
const ang = 25;
const numGens = 6;
let drawRules;
let word = "X";

function preload()
{
	soundFormats('mp3', "wav");
  song = loadSound('https://openprocessing.org/sketch/2262008/files/Joe-GardenSong.mp3');//load song
}


let rules = 
{
  X: [
    // Original rule
    { rule: "F[+X][-X]FX",  prob: 0.5 },

    // Fewer limbs
    { rule: "F[-X]FX",      prob: 0.05 },
    { rule: "F[++X]FX",      prob: 0.05 },

    // Extra rotation
    { rule: "F[++X][-X]FX", prob: 0.1 },
    { rule: "F[+X][--X]FX", prob: 0.1 },

    // Berries/fruits
    { rule: "F[+X][-X]FA",  prob: 0.1 },
    { rule: "F[+X][-X]FB",  prob: 0.1 }
  ],
  F: [
    // Original rule
    { rule: "FF",  prob: 0.85 },

    // Extra growth
    { rule: "FFF", prob: 0.05 },

    // Stunted growth
    { rule: "F",   prob: 0.1 },
  ]
};


function setup() 
{
	background("green")
	fft = new p5.FFT();
	fft.setInput(song);	
	song.play()
	song.loop()
  createCanvas(windowWidth, windowHeight);
  strokeWeight(2);

  drawRules = {
    "A": () => {
      // Draw circle at current location
      noStroke();
			if(B>46) 
			{
				fill(random(255),0,0)
				textSize(random(len*5))
				stroke(random(255))
				strokeWeight(random(5))
				text("♪",0,0)
			}
      else fill("#E5CEDC");

      circle(0, 0, len*2);
    },  
    "B": () => {
      // Draw circle at current location
      noStroke();
			if(B>46) fill(random(255),0,0)
      else fill("#FCA17D");
      circle(0, 0, len*2);
    },
    "F": () => {
      // Draw line forward, then move to end of line
			strokeWeight(B/10)
      line(0, 0, 0, -len);
      translate(0, -len);
    },
    "+": () => {
      // Rotate right
      rotate(PI/180 * -ang);
    },
    "-": () => {
      // Rotate right
      rotate(PI/180 * ang);
    },
    // Save current location
    "[": push,
    // Restore last location
    "]": pop,
  };
}

function draw() 
{ 
	let spectrum = fft.analyze();
	let bass
	bass = fft.getEnergy("bass");
	B = map(bass, 0, 300, 0, 60, true);

	if(B>46.8) len=B/random(4,6)
	else len=4

	if(B<41) frameRate(B/1.5)
	else frameRate(60)
	let g=get()

	push()
	if(B>46) image(g, random(-10,10), 0, width, height*B/40) //shakes feedback loop 
	else image(g, 0, 0, width, height*B/40) //feedback loop 
  for(i=0;i<B/25;i++) //how many trees to generate every frame
  {
		// Generate our L-System from the start
		word = "X";
		for(let i = 0; i < numGens; i ++) 
		{
			branchColor[numGens]=random(100)
			word = generate();
		}
		// Draw L-System 
			push();
			if(B<40) translate(random(width), height-50);
			else translate(random(width), height-random(50,100));
			for(let i = 0; i < word.length; i ++) 
			{
				let c = word[i];
				if(c in drawRules) 
				{
					if(c=="F") stroke(0,branchColor[i],0)
					drawRules[c]();
				}  
			}
			pop();
  }
}

function generate() 
{
  let next = ""  
  for(let i = 0; i < word.length; i ++) 
	{
    var c = word[i];
    if(c in rules) 
		{
      let rule = rules[c];

      // Check if we're using an array or not
      if(Array.isArray(rule)) 
			{
        next += chooseOne(rule); // If we are, choose one of the options
      } 
			else 
			{
        next += rules[c]; // Otherwise use the rule directly
      }
    } 
		else 
		{
      next += c;
    }
  }

  return next;
}

function chooseOne(ruleSet) 
{
  let n = random(); // Random number between 0-1
  let t = 0;
  for(let i = 0; i < ruleSet.length; i++) 
	{
    t += ruleSet[i].prob; // Keep adding the probability of the options to total
    if(t > n) 
		{ // If the total is more than the random value
      return ruleSet[i].rule; // Choose that option																																																																																																																																						You did it!!  Mini game link!:   oppr.org/s/saicqVTR																																			
    }
  }
  return "";
}
